-    let mut collected = GenerationOutput::default();
-    while let Some(item) = events.next().await {
-        let output = item?;
-        let finished = output.finish_reason.is_some();
-        fold_output(&mut collected, output);
-        if finished {
-            return Ok(collected);
-        }
-    }
