-        }
-        state.active.fetch_sub(1, Ordering::SeqCst);
-
-        let frame = serde_json::json!({
-            "output_ids": [104],
-            "meta_info": {
-                "prompt_tokens": 1,
-                "completion_tokens": 1,
-                "finish_reason": {"type": "stop", "matched": choice + 10}
-            }
-        })
-        .to_string();
