-fn semantic_chat_stream(
-    submitted: Vec<(usize, GenerationStream)>,
-    response_processor: ChatResponseProcessor,
-    want_logprobs: bool,
-) -> impl futures::Stream<Item = Result<ChatEvent, ResponseError>> {
