-        Some(OneOrMany::Many(values)) if values.len() == prompt_count => {
-            Ok(values.into_iter().map(Some).collect())
-        }
-        Some(OneOrMany::Many(values)) => Err(format!(
-            "the length of {name} must equal the prompt batch size ({prompt_count}), got {}",
-            values.len()
-        )),
-    }
