-                .as_f64()
-                .ok_or_else(|| format!("logit_bias[{token:?}] must be a number"))?;
-            logit_bias.insert(token.clone(), bias);
-        }
-    }
-
-    Ok(SamplingParams {
-        max_new_tokens: Some(request.max_tokens.unwrap_or(16) as i64),
-        stop,
-        stop_token_ids,
-        temperature: request
-            .temperature
-            .map(f64::from)
