-fn contains_media(value: &JsonValue) -> bool {
-    match value {
-        JsonValue::Array(values) => values.iter().any(contains_media),
-        JsonValue::Object(object) => {
-            object.keys().any(|key| {
-                matches!(
-                    key.as_str(),
-                    "image_url" | "video_url" | "input_audio" | "audio_url" | "file"
