-/// Whether `ast` can match more than one length — the property that makes a
-/// repetition of it ambiguous.
-fn is_variable_length(ast: &regex_syntax::ast::Ast) -> bool {
-    let (lo, hi) = ast_len(ast);
-    hi != Some(lo)
-}
