-    for &id in token_ids_logprob.iter().flat_map(|ids| ids.iter()) {
-        if id < 0 || id as u64 >= limits.vocab_size {
-            return Err(Error::Validation(format!(
-                "token_ids_logprob contains out-of-vocabulary token id {id}; valid range is [0, {})",
